node --input-type=module -e '
import { Inventory } from "./src/inventory.js";
import assert from "node:assert/strict";
let inv = new Inventory();
inv.add("X", 5);
inv.reserve("X", 3);
inv.remove("X", 2); // exactly up to reserved
assert.deepEqual(inv.snapshot(), [{ sku: "X", onHand: 3, reserved: 3, available: 0 }]);
assert.throws(() => inv.remove("X", 1), RangeError);

// R7: code-unit sort, e.g. "-" (0x2D) < "a" but localeCompare may differ
inv = new Inventory();
inv.add("a-b", 1);
inv.add("ab", 1);
assert.deepEqual(inv.snapshot().map(s => s.sku), ["a-b", "ab"]);

// R1: non-string / empty sku throw TypeError on all methods
inv = new Inventory();
for (const bad of [123, null, "  "]) {
  assert.throws(() => inv.add(bad, 1), TypeError);
  assert.throws(() => inv.reserve(bad, 1), TypeError);
  assert.throws(() => inv.release(bad, 1), TypeError);
  assert.throws(() => inv.remove(bad, 1), TypeError);
}
// R2: bad quantities
for (const bad of [0, -1, 1.5, "5", NaN]) {
  assert.throws(() => inv.add("X", bad), RangeError);
}
// R4/R5: nothing changes on failed ops
inv.add("X", 5);
assert.throws(() => inv.reserve("X", 6), RangeError);
assert.throws(() => inv.release("X", 1), RangeError);
assert.deepEqual(inv.snapshot(), [{ sku: "X", onHand: 5, reserved: 0, available: 5 }]);
// R7: empty sku left out
inv.remove("X", 5);
assert.deepEqual(inv.snapshot(), []);
console.log("all rule checks passed");
'

